require_once(__DIR__ . '/../init.php'); require_once 'mcs.php'; require_once 'belcmt.php'; class talonbox_talonbox { const DEBUG = false; const DEBUG_HTTP = false; const LOG_DBG = -1; const LOG_INFO = 0; const LOG_WARN = 1; const LOG_ERR = 2; const LOG_END = 3; const ERROR_NOT_AVAILABLE = -1000; const ERROR_UNKNOWN_SVC_TYPE = -1001; const MAP = 'map'; const BELCMT = 'belcmt'; public $cfg = null; private function getSvc() { $this->doLog('talonbox [getSvc]', self::LOG_DBG); switch ($this->cfg->connect->type) { case self::MAP: return new mcs($this); case self::BELCMT: return new belcmt($this); default: break; } $this->doLog('[getSvc] Неизвестный тип подключения (' . $this->cfg->connect->type.')', self::LOG_ERR); return false; } public function doLog($message, $type = self::LOG_INFO) { if (!self::DEBUG && $type = self::LOG_DBG) { return; } app_log($message, $type = self::LOG_DBG ? self::LOG_INFO : $type, 'talonbox'); } private function getSettings() { if ($this->cfg) { return $this->cfg; } $this->doLog('talonbox [getSettings]', self::LOG_DBG); $this->cfg = readJsonSettings('settings_talonbox', false); return $this->cfg; } public function ping() { $this->doLog('talonbox [ping]', self::LOG_DBG); $obj = getSessionValue('talonbox'); if (!is_object($obj)) { setSessionValue('talonbox', $obj = new stdClass()); } $res = new stdClass(); $res->ec = self::ERROR_NOT_AVAILABLE; try { $res->cfg = $this->getSettings(); $res->ec = self::ERROR_UNKNOWN_SVC_TYPE; if (!($svc = $this->getSvc())) { return $res; } $svcRes = $svc->ping(); $res->dateTime = date('D M d Y H:i:s'); $res->ec = 0; } catch (Throwable $e) { $res->ec = $e->getCode(); $this->doLog('[ping] ' . $e, self::LOG_ERR); throw $e; } return $res; } public function getProfessions($params) { $this->doLog('talonbox [getProfessions]', self::LOG_DBG); $this->getSettings(); if (!($svc = $this->getSvc())) { return; } return $svc->getProfessions( isUndefinedProperty($params, 'id', 0), isUndefinedProperty($params, 'mode', 1) ); } public function getDoctors($params) { $this->doLog('talonbox [getDoctors] ' . print_r($params, true), self::LOG_DBG); $this->getSettings(); if (!($svc = $this->getSvc())) { return; } return $svc->getDoctors( isUndefinedProperty($params, 'professionId', 0), isUndefinedProperty($params, 'mode', 1), isEmptyProperty($params, 'doctorIdList'), isEmptyProperty($params, 'structureId'), isEmptyProperty($params, 'territoryDoctorId') ); } public function getCalendar($params) { $this->doLog('talonbox [getCalendar]', self::LOG_DBG); $this->getSettings(); if (!($svc = $this->getSvc())) { return; } return $svc->getCalendar( isUndefinedProperty($params, 'professionId', 0), isUndefinedProperty($params, 'doctorId', 0), isUndefinedProperty($params, 'patientId', 0), isUndefinedProperty($params, 'mode', 1) ); } public function getCoupons($params) { $this->doLog('talonbox [getCoupons]', self::LOG_DBG); $this->getSettings(); if (!($svc = $this->getSvc())) { return; } return $svc->getCoupons( isUndefinedProperty($params, 'professionId', 0), isUndefinedProperty($params, 'doctorId', 0), isUndefinedProperty($params, 'onDate'), isUndefinedProperty($params, 'patientId', 0), isUndefinedProperty($params, 'mode', 1) ); } public function authorize($params) { $this->doLog('talonbox [authorize] ' . print_r($params, true), self::LOG_DBG); $this->getSettings(); if (!($svc = $this->getSvc())) { return; } $isBelcmt = $this->cfg->connect->type == self::BELCMT; $surname = isUndefinedProperty($params, 'surname'); $barcode = is_numeric($surname[0]) ? $surname : null; $surname = $this->encodeParam($params, 'surname'); $surname = $surname ? $surname . "%" : ""; $name = $this->encodeParam($params, 'name', '', !$isBelcmt); $name = $name ? $name . "%" : ""; $patronymic = $this->encodeParam($params, 'patronymic', '', !$isBelcmt); $patronymic = $patronymic ? $patronymic . "%" : ""; $birthDate = isEmptyProperty($params, 'birthDate', date('Y-m-d')); $city = $this->encodeParam($params, 'city'); $city = $city ? $city . "%" : ""; $street = $this->encodeParam($params, 'street'); $street = $street ? "%" . $street . "%" : ""; $house = $this->encodeParam($params, 'house'); $corpus = $this->encodeParam($params, 'corpus'); $corpus = $corpus ? $corpus . "%" : ""; $flat = $this->encodeParam($params, 'flat'); if (!empty($barcode) && $this->cfg->connect->type == self::MAP) { $ret = $svc->authorizeByBarcode($barcode); } else { $ret = $svc->authorize( $surname, $name, $patronymic, $birthDate, $city, $street, $house, $corpus, $flat ); } return $ret; } private function encodeParam($object, $property, $default = '', $isChangeVowels = true) { $this->doLog('talonbox [encodeParam]', self::LOG_DBG); $ret = mb_strtolower(empty($object->$property) ? $default : $object->$property, 'UTF-8'); if ($isChangeVowels) { $vowels = array("а", "е", "и", "о", "у", "ю", "ы", "э", "я", "ё"); $ret = str_replace($vowels, "_", $ret); } return $ret; } public function reserveCoupon($params) { $this->doLog('talonbox [reserveCoupon] ' . print_r($params, true), self::LOG_DBG); $this->getSettings(); if (!($svc = $this->getSvc())) { return; } $ret = $svc->reserveCoupon( isUndefinedProperty($params, 'couponId', 0), isUndefinedProperty($params, 'patientId', null), isUndefinedProperty($params, 'patientFio', '') ); return $ret; } public function getPatientCoupons($params) { $this->doLog('talonbox [getPatientCoupons] ' . print_r($params, true), self::LOG_DBG); $patientId = isUndefinedProperty($params, 'patientId', 0); $kioskNumber = isUndefinedProperty($params, 'kioskNumber', 0); $isFullList = isUndefinedProperty($params, 'fullList', 0) == 1; $this->getSettings(); if (!($svc = $this->getSvc())) { return; } $ret = $svc->getPatientCoupons($patientId, $kioskNumber, $isFullList); return $ret; } public function cancelCoupon($params) { $this->doLog('talonbox [cancelCoupon] ' . print_r($params, true), self::LOG_DBG); $this->getSettings(); if (!($svc = $this->getSvc())) { return; } $ret = $svc->cancelCoupon( isUndefinedProperty($params, 'couponI