unction checkEqueueBarcode($params = null) { $this->doLog('talonbox [checkEqueueBarcode]', self::LOG_DBG); $this->getSettings(); $svc = new mcs($this); $ret = $svc->checkEqueueBarcode($params); return $ret; } public function getPatientOrders($params) { $this->doLog('talonbox [getPatientOrders] ' . print_r($params, true), self::LOG_DBG); $patientId = isUndefinedProperty($params, 'patientId', 0); $kioskNumber = isUndefinedProperty($params, 'kioskNumber', 0); $this->getSettings(); if (!($svc = $this->getSvc())) { return; } $ordersValidityMonths = !empty($this->cfg->ordersValidityMonths) ? $this->cfg->ordersValidityMonths : 3; $ret = $svc->getPatientOrders($patientId, $kioskNumber, $ordersValidityMonths); return $ret; } public function getCouponShortNumberByVisitTime($params) { $this->doLog('[getCouponShortNumberByVisitDateAndDoctor] ' . print_r($params, true), self::LOG_DBG); $this->getSettings(); if (!($svc = $this->getSvc())) { return null; } return $svc->getCouponShortNumberByVisitDateAndDoctor($params); } } handleJsonRpc('talonbox_talonbox');